<?php
/**
 * Admin Module: Founder Share & Invite Links Attribution Hub
 * Comprehensive control room to track, inspect, and manage every share invite generated by founders.
 * Displays which founder shared the invite, whose invite it was (recipient & role type),
 * live link clicks, registered conversions, and deal room engagement.
 */
require_once __DIR__ . '/../config.php';
$user = require_auth('admin');
$db = get_db();
$pageTitle = 'Founder Share Invites & Attribution';

$error = '';
$flash = get_flash();

// Handle CSV Export
if (isset($_GET['action']) && $_GET['action'] === 'export_csv') {
    $search = trim($_GET['search'] ?? '');
    $filterType = trim($_GET['type'] ?? '');
    $filterStatus = trim($_GET['status'] ?? '');
    $filterFounder = (int)($_GET['founder_id'] ?? 0);

    $sql = "
        SELECT 
            i.id,
            i.invite_code,
            i.invite_type,
            i.recipient_name,
            i.recipient_email,
            i.status,
            i.views_count,
            i.custom_note,
            i.created_at,
            i.expires_at,
            u.name AS founder_name,
            u.email AS founder_email,
            c.id AS company_id,
            c.name AS company_name,
            c.industry AS company_industry,
            c.stage AS company_stage,
            ru.name AS registered_name,
            ru.email AS registered_email,
            ru.role AS registered_role,
            ru.created_at AS registered_at
        FROM founder_invites i
        JOIN users u ON i.founder_id = u.id
        JOIN companies c ON i.company_id = c.id
        LEFT JOIN users ru ON i.invited_user_id = ru.id
        WHERE 1=1
    ";
    $params = [];

    if ($filterFounder > 0) {
        $sql .= " AND i.founder_id = ?";
        $params[] = $filterFounder;
    }
    if (!empty($filterType)) {
        $sql .= " AND i.invite_type = ?";
        $params[] = $filterType;
    }
    if (!empty($filterStatus)) {
        $sql .= " AND i.status = ?";
        $params[] = $filterStatus;
    }
    if (!empty($search)) {
        $sql .= " AND (
            u.name LIKE ? OR 
            u.email LIKE ? OR 
            c.name LIKE ? OR 
            i.recipient_name LIKE ? OR 
            i.recipient_email LIKE ? OR 
            i.invite_code LIKE ?
        )";
        $searchTerm = "%{$search}%";
        $params = array_merge($params, [$searchTerm, $searchTerm, $searchTerm, $searchTerm, $searchTerm, $searchTerm]);
    }
    $sql .= " ORDER BY i.created_at DESC";

    $stmt = $db->prepare($sql);
    $stmt->execute($params);
    $rows = $stmt->fetchAll(PDO::FETCH_ASSOC);

    header('Content-Type: text/csv; charset=utf-8');
    header('Content-Disposition: attachment; filename=founder_invites_attribution_' . date('Ymd_His') . '.csv');
    header('Pragma: no-cache');
    header('Expires: 0');

    $output = fopen('php://output', 'w');
    // Add UTF-8 BOM
    fputs($output, "\xEF\xBB\xBF");

    // CSV Header
    fputcsv($output, [
        'Invite ID',
        'Invite Code',
        'Target Role / Type',
        'Founder Name (Originator)',
        'Founder Email',
        'Startup / Company',
        'Industry',
        'Stage',
        'Recipient Name',
        'Recipient Email',
        'Attribution Status',
        'Total Views / Clicks',
        'Registered Invitee Name',
        'Registered Invitee Email',
        'Registered User Role',
        'Custom Pitch Note',
        'Full Share URL',
        'Created At',
        'Expires At'
    ], ',', '"', '\\');

    foreach ($rows as $r) {
        $compHash = hash_id_encode($r['company_id']);
        $shareUrl = rtrim(BASE_URL, '/') . '/company.php?id=' . $compHash . '&invite=' . urlencode($r['invite_code']);
        fputcsv($output, [
            $r['id'],
            $r['invite_code'],
            strtoupper($r['invite_type']),
            $r['founder_name'],
            $r['founder_email'],
            $r['company_name'],
            $r['company_industry'] ?? 'N/A',
            $r['company_stage'] ?? 'N/A',
            $r['recipient_name'] ?: 'Public / Open Link',
            $r['recipient_email'] ?: 'N/A',
            strtoupper($r['status']),
            $r['views_count'],
            $r['registered_name'] ?: 'None',
            $r['registered_email'] ?: 'None',
            $r['registered_role'] ?: 'None',
            $r['custom_note'] ?: '',
            $shareUrl,
            $r['created_at'],
            $r['expires_at'] ?: 'Never'
        ], ',', '"', '\\');
    }
    fclose($output);
    exit;
}

// Handle POST actions
if (($_SERVER['REQUEST_METHOD'] ?? '') === 'POST' && $db) {
    if (!verify_csrf($_POST['csrf_token'] ?? '')) {
        $error = 'Invalid security token or expired session. Please refresh and try again.';
    } else {
        $action = $_POST['form_action'] ?? '';

        // 1. CREATE NEW FOUNDER INVITE LINK
        if ($action === 'create_invite') {
            $companyId = (int)($_POST['company_id'] ?? 0);
            $inviteType = trim($_POST['invite_type'] ?? 'investor');
            $recipientName = trim($_POST['recipient_name'] ?? '');
            $recipientEmail = trim($_POST['recipient_email'] ?? '');
            $customNote = trim($_POST['custom_note'] ?? '');
            $expiresDays = (int)($_POST['expires_days'] ?? 30);
            $sendEmail = isset($_POST['send_email']) && $_POST['send_email'] === '1';

            // Validate company & derive founder
            $compStmt = $db->prepare("
                SELECT c.id, c.name, cf.user_id as founder_id, u.name as founder_name
                FROM companies c
                LEFT JOIN company_founders cf ON c.id = cf.company_id
                LEFT JOIN users u ON cf.user_id = u.id
                WHERE c.id = ?
                LIMIT 1
            ");
            $compStmt->execute([$companyId]);
            $comp = $compStmt->fetch(PDO::FETCH_ASSOC);

            if (!$comp) {
                $error = 'Please select a valid startup company.';
            } else {
                $founderId = (int)($comp['founder_id'] ?? 0);
                if ($founderId <= 0) {
                    // Fallback to first founder in users table or admin
                    $firstFounder = $db->query("SELECT id FROM users WHERE role = 'founder' LIMIT 1")->fetchColumn();
                    $founderId = $firstFounder ? (int)$firstFounder : $user['id'];
                }

                // Generate clean, readable, unique invite code
                $cleanCompName = strtoupper(substr(preg_replace('/[^a-zA-Z0-9]/', '', $comp['name']), 0, 4)) ?: 'COMP';
                $cleanType = match($inviteType) {
                    'investor' => 'INV',
                    'co_founder' => 'COF',
                    'advisor' => 'ADV',
                    default => 'SHR'
                };
                $recipientSlug = '';
                if (!empty($recipientName)) {
                    $recipientSlug = strtoupper(substr(preg_replace('/[^a-zA-Z0-9]/', '', $recipientName), 0, 4)) . '-';
                }
                $inviteCode = 'INV-' . $cleanCompName . '-' . $recipientSlug . $cleanType . '-' . strtoupper(bin2hex(random_bytes(2)));

                $expiresAt = null;
                if ($expiresDays > 0) {
                    $expiresAt = date('Y-m-d H:i:s', strtotime("+{$expiresDays} days"));
                }

                try {
                    $ins = $db->prepare("
                        INSERT INTO founder_invites 
                        (founder_id, company_id, invite_code, invite_type, recipient_name, recipient_email, status, views_count, custom_note, expires_at, created_at)
                        VALUES (?, ?, ?, ?, ?, ?, 'pending', 0, ?, ?, NOW())
                    ");
                    $ins->execute([
                        $founderId,
                        $companyId,
                        $inviteCode,
                        $inviteType,
                        $recipientName ?: null,
                        $recipientEmail ?: null,
                        $customNote ?: null,
                        $expiresAt
                    ]);
                    $newInviteId = (int)$db->lastInsertId();

                    $emailDispatchedNotice = '';
                    if ($sendEmail && !empty($recipientEmail)) {
                        require_once __DIR__ . '/../includes/mailer.php';
                        $mailRes = send_founder_invite_email($db, $newInviteId);
                        if ($mailRes['success']) {
                            $emailDispatchedNotice = ' and invitation email was dispatched to ' . htmlspecialchars($recipientEmail);
                        } else {
                            $emailDispatchedNotice = ' (Warning: Email dispatch failed: ' . htmlspecialchars($mailRes['message'] ?? 'smtp error') . ')';
                        }
                    }

                    log_audit(
                        $user['id'],
                        'CREATE_FOUNDER_INVITE',
                        'founder_invites',
                        $newInviteId,
                        "Created {$inviteType} invite '{$inviteCode}' for {$recipientName} on behalf of {$comp['name']}"
                    );

                    set_flash('success', "Founder share link '{$inviteCode}' generated successfully{$emailDispatchedNotice}!");
                    header('Location: ' . url('admin/founder_invites.php'));
                    exit;
                } catch (Exception $e) {
                    $error = 'Failed to generate invite: ' . $e->getMessage();
                }
            }
        }

        // 2. RESEND INVITATION EMAIL
        elseif ($action === 'resend_email') {
            $inviteId = (int)($_POST['invite_id'] ?? 0);
            if ($inviteId <= 0) {
                $error = 'Invalid invite specified.';
            } else {
                require_once __DIR__ . '/../includes/mailer.php';
                $mailRes = send_founder_invite_email($db, $inviteId);
                if ($mailRes['success']) {
                    log_audit($user['id'], 'RESEND_FOUNDER_INVITE_EMAIL', 'founder_invites', $inviteId, "Resent invite email for invite #{$inviteId}");
                    set_flash('success', "Invitation email re-dispatched successfully!");
                    header('Location: ' . url('admin/founder_invites.php'));
                    exit;
                } else {
                    $error = 'Could not send email: ' . ($mailRes['message'] ?? 'Recipient email missing or mail service unavailable.');
                }
            }
        }

        // 3. DELETE / REVOKE INVITE
        elseif ($action === 'delete_invite') {
            $inviteId = (int)($_POST['invite_id'] ?? 0);
            if ($inviteId <= 0) {
                $error = 'Invalid invite record specified.';
            } else {
                try {
                    $codeStmt = $db->prepare("SELECT invite_code FROM founder_invites WHERE id = ?");
                    $codeStmt->execute([$inviteId]);
                    $invCode = $codeStmt->fetchColumn() ?: "#{$inviteId}";

                    $delStmt = $db->prepare("DELETE FROM founder_invites WHERE id = ?");
                    $delStmt->execute([$inviteId]);

                    log_audit($user['id'], 'REVOKE_FOUNDER_INVITE', 'founder_invites', $inviteId, "Revoked invite link '{$invCode}'");
                    set_flash('success', "Invite link '{$invCode}' has been revoked and removed.");
                    header('Location: ' . url('admin/founder_invites.php'));
                    exit;
                } catch (Exception $e) {
                    $error = 'Error revoking invite: ' . $e->getMessage();
                }
            }
        }
    }
}

// -------------------------------------------------------------
// METRICS & STATS
// -------------------------------------------------------------
$totalInvites = 0;
$totalViews = 0;
$totalRegistered = 0;
$totalConverted = 0;
$investorInvitesCount = 0;
$coFounderInvitesCount = 0;
$advisorInvitesCount = 0;
$generalShareCount = 0;

try {
    $totalInvites = (int)$db->query("SELECT COUNT(*) FROM founder_invites")->fetchColumn();
    $totalViews = (int)$db->query("SELECT COALESCE(SUM(views_count), 0) FROM founder_invites")->fetchColumn();
    $totalRegistered = (int)$db->query("SELECT COUNT(*) FROM founder_invites WHERE status IN ('registered', 'converted') OR invited_user_id IS NOT NULL")->fetchColumn();
    $totalConverted = (int)$db->query("SELECT COUNT(*) FROM founder_invites WHERE status = 'converted'")->fetchColumn();

    $typeBreakdown = $db->query("SELECT invite_type, COUNT(*) as cnt FROM founder_invites GROUP BY invite_type")->fetchAll(PDO::FETCH_KEY_PAIR);
    $investorInvitesCount = (int)($typeBreakdown['investor'] ?? 0);
    $coFounderInvitesCount = (int)($typeBreakdown['co_founder'] ?? 0);
    $advisorInvitesCount = (int)($typeBreakdown['advisor'] ?? 0);
    $generalShareCount = (int)($typeBreakdown['general_share'] ?? 0);
} catch (Exception $e) {}

// Calculate Conversion Rate
$signupRate = $totalViews > 0 ? round(($totalRegistered / $totalViews) * 100, 1) : 0;
$dealConvRate = $totalInvites > 0 ? round(($totalConverted / $totalInvites) * 100, 1) : 0;

// -------------------------------------------------------------
// FILTER CONTROLS & QUERY
// -------------------------------------------------------------
$filterFounder = (int)($_GET['founder_id'] ?? 0);
$filterType = trim($_GET['type'] ?? '');
$filterStatus = trim($_GET['status'] ?? '');
$search = trim($_GET['search'] ?? '');

$query = "
    SELECT 
        i.*,
        u.id AS founder_id,
        u.name AS founder_name,
        u.email AS founder_email,
        u.avatar_url AS founder_avatar,
        u.status AS founder_status,
        c.id AS company_id,
        c.name AS company_name,
        c.logo_url AS company_logo,
        c.industry AS company_industry,
        c.stage AS company_stage,
        ru.id AS registered_user_id,
        ru.name AS registered_name,
        ru.email AS registered_email,
        ru.role AS registered_role,
        ru.created_at AS registered_at
    FROM founder_invites i
    JOIN users u ON i.founder_id = u.id
    JOIN companies c ON i.company_id = c.id
    LEFT JOIN users ru ON i.invited_user_id = ru.id
    WHERE 1=1
";
$queryParams = [];

if ($filterFounder > 0) {
    $query .= " AND i.founder_id = ?";
    $queryParams[] = $filterFounder;
}
if (!empty($filterType)) {
    $query .= " AND i.invite_type = ?";
    $queryParams[] = $filterType;
}
if (!empty($filterStatus)) {
    $query .= " AND i.status = ?";
    $queryParams[] = $filterStatus;
}
if (!empty($search)) {
    $query .= " AND (
        u.name LIKE ? OR 
        u.email LIKE ? OR 
        c.name LIKE ? OR 
        i.recipient_name LIKE ? OR 
        i.recipient_email LIKE ? OR 
        i.invite_code LIKE ?
    )";
    $term = "%{$search}%";
    $queryParams = array_merge($queryParams, [$term, $term, $term, $term, $term, $term]);
}

$query .= " ORDER BY i.created_at DESC";
$stmt = $db->prepare($query);
$stmt->execute($queryParams);
$invites = $stmt->fetchAll(PDO::FETCH_ASSOC);

// Fetch Founders who have created invites (for the filter dropdown)
$foundersList = $db->query("
    SELECT DISTINCT u.id, u.name, u.email, COUNT(i.id) as invite_count
    FROM users u
    JOIN founder_invites i ON u.id = i.founder_id
    GROUP BY u.id, u.name, u.email
    ORDER BY u.name ASC
")->fetchAll(PDO::FETCH_ASSOC);

// Fetch Companies with their Founders for the "Create Invite" Modal
$availableCompanies = $db->query("
    SELECT c.id, c.name, c.industry, c.stage,
           COALESCE(u.id, 0) as founder_id,
           COALESCE(u.name, 'Founder') as founder_name,
           COALESCE(u.email, '') as founder_email
    FROM companies c
    LEFT JOIN company_founders cf ON c.id = cf.company_id
    LEFT JOIN users u ON cf.user_id = u.id
    ORDER BY c.name ASC
")->fetchAll(PDO::FETCH_ASSOC);

?>
