    <!-- Toast Notification for 1-Click Copy -->
    <div id="copyToast" class="fixed bottom-5 right-5 z-50 hidden bg-slate-900 text-white text-xs font-semibold px-4 py-2.5 rounded-xl shadow-xl flex items-center gap-2 border border-slate-700 transition transform">
        <i data-lucide="check-circle" class="w-4 h-4 text-emerald-400"></i>
        <span id="copyToastText">Share link copied to clipboard!</span>
    </div>

    <script>
        // Initialize Lucide icons
        lucide.createIcons();

        // -------------------------------------------------------------
        // CLIENT-SIDE INSTANT SEARCH
        // -------------------------------------------------------------
        const liveSearchInput = document.getElementById('liveSearchInput');
        const tableRows = document.querySelectorAll('#invitesTable tbody tr.invite-row');
        const resultsCountBadge = document.getElementById('resultsCountBadge');

        if (liveSearchInput) {
            liveSearchInput.addEventListener('input', function(e) {
                const term = e.target.value.toLowerCase().trim();
                let matched = 0;

                tableRows.forEach(row => {
                    const rowSearchText = row.getAttribute('data-search') || '';
                    if (!term || rowSearchText.includes(term)) {
                        row.style.display = '';
                        matched++;
                    } else {
                        row.style.display = 'none';
                    }
                });

                if (resultsCountBadge) {
                    resultsCountBadge.textContent = matched + ' Records';
                }
            });
        }

        // -------------------------------------------------------------
        // CLIPBOARD COPY
        // -------------------------------------------------------------
        function copyShareUrl(url, buttonEl) {
            navigator.clipboard.writeText(url).then(() => {
                showToast('Share link copied to clipboard!');
                if (buttonEl) {
                    const icon = buttonEl.querySelector('svg');
                    if (icon) {
                        icon.classList.add('text-emerald-500');
                        setTimeout(() => {
                            icon.classList.remove('text-emerald-500');
                        }, 1800);
                    }
                }
            }).catch(err => {
                // Fallback for older browsers
                const tmp = document.createElement('textarea');
                tmp.value = url;
                document.body.appendChild(tmp);
                tmp.select();
                document.execCommand('copy');
                document.body.removeChild(tmp);
                showToast('Share link copied to clipboard!');
            });
        }

        function copyQrUrl() {
            const input = document.getElementById('qrUrlInput');
            if (input) {
                navigator.clipboard.writeText(input.value).then(() => {
                    showToast('URL copied to clipboard!');
                    const icon = document.getElementById('qrCopyIcon');
                    if (icon) {
                        icon.classList.add('text-emerald-500');
                        setTimeout(() => {
                            icon.classList.remove('text-emerald-500');
                        }, 1800);
                    }
                });
            }
        }

        function showToast(text) {
            const toast = document.getElementById('copyToast');
            const toastText = document.getElementById('copyToastText');
            if (!toast) return;
            if (toastText) toastText.textContent = text;
            toast.classList.remove('hidden');
            setTimeout(() => {
                toast.classList.add('hidden');
            }, 2500);
        }

        // -------------------------------------------------------------
        // MODALS CONTROL
        // -------------------------------------------------------------
        function openCreateModal() {
            document.getElementById('createModal')?.classList.remove('hidden');
            lucide.createIcons();
        }

        function closeCreateModal() {
            document.getElementById('createModal')?.classList.add('hidden');
        }

        function handleCompanyChange(selectEl) {
            const opt = selectEl.options[selectEl.selectedIndex];
            const founderName = opt.getAttribute('data-founder');
            const founderDisplay = document.getElementById('founderNameDisplay');
            const infoBox = document.getElementById('companyFounderInfo');

            if (founderName && founderName !== '--') {
                if (founderDisplay) founderDisplay.textContent = founderName;
                if (infoBox) infoBox.classList.remove('hidden');
            } else {
                if (infoBox) infoBox.classList.add('hidden');
            }
        }

        function openQrModal(url, code, company, recipient) {
            const modal = document.getElementById('qrModal');
            if (!modal) return;

            document.getElementById('qrModalCompany').textContent = company;
            document.getElementById('qrModalRecipient').textContent = recipient;
            document.getElementById('qrModalCode').textContent = code;
            document.getElementById('qrUrlInput').value = url;
            document.getElementById('qrTestLink').href = url;

            // Generate high-definition QR Code via reliable QR API
            const qrImg = document.getElementById('qrImageElement');
            if (qrImg) {
                qrImg.src = 'https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=' + encodeURIComponent(url);
            }

            modal.classList.remove('hidden');
            lucide.createIcons();
        }

        function closeQrModal() {
            document.getElementById('qrModal')?.classList.add('hidden');
        }

        function openDeleteModal(id, code) {
            document.getElementById('deleteInviteId').value = id;
            document.getElementById('deleteInviteCode').textContent = code;
            document.getElementById('deleteModal')?.classList.remove('hidden');
            lucide.createIcons();
        }

        function closeDeleteModal() {
            document.getElementById('deleteModal')?.classList.add('hidden');
        }

        // Close modals on Esc key
        document.addEventListener('keydown', function(e) {
            if (e.key === 'Escape') {
                closeCreateModal();
                closeQrModal();
                closeDeleteModal();
            }
        });
    </script>
